window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-dffd4a9f4f6752be"]={"versions": [{"id": "FIG-dffd4a9f4f6752be", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm im Kontext der AUTOSAR Classic Platform (Diagnostic Stack). Dargestellt wird die Interaktion zur Abfrage des DTC-Status zwischen einem externen Diagnoseprüfgerät (Generic Scan Tool), dem Diagnostic Communication Manager (Dcm) und dem Diagnostic Event Manager (Dem).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten und Schnittstellen:</p>\n<ul class=\"fig-list\"><li><strong>Generic Scan Tool</strong>: Externer UDS-Tester / Diagnosetester.\n</li><li><strong>«module» Dcm</strong>: AUTOSAR-Basissoftwaremodul für Diagnosekommunikation.\n</li><li><strong>«module» Dem</strong>: AUTOSAR-Basissoftwaremodul für Fehlerspeicherverwaltung und DTC-Status.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li>UDS-Dienstaufruf: <code>Request: ReadDTCInformation(reportDTCByStatusMask)</code> (Service 0x19, Subfunktion 0x02) vom Tester an den Dcm.\n</li><li>C-API: <code>Dem_DcmGetDTCStatusAvailabilityMask(Std_ReturnType, Dem_UdsStatusByteType*)</code> zwischen Dcm und Dem.\n</li><li>C-API: <code>Dem_DcmGetStatusOfDTC(Dem_ReturnGetStatusOfDTCType, uint32, Dem_DTCOriginType, uint8*)</code> zwischen Dcm und Dem.\n</li><li>Diagnose-Antwort: <code>Positive or negative response()</code> vom Dcm an das Generic Scan Tool.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Das <strong>Generic Scan Tool</strong> sendet die Diagnoseanfrage <code>Request: ReadDTCInformation(reportDTCByStatusMask)</code> synchron/asynchron an das Modul <strong>Dcm</strong>.\n</li><li>Der <strong>Dcm</strong> ruft am <strong>Dem</strong> synchron die Funktion <code>Dem_DcmGetDTCStatusAvailabilityMask(...)</code> auf, um die unterstützte UDS-Statusmaske (<code>Dem_UdsStatusByteType*</code>) zu ermitteln, und erhält den Rückgabewert (<code>Std_ReturnType</code>).\n</li><li>Anschließend ruft der <strong>Dcm</strong> am <strong>Dem</strong> die Funktion <code>Dem_DcmGetStatusOfDTC(...)</code> mit den Parametern DTC-Wert (<code>uint32</code>), DTC-Herkunft/Speicherort (<code>Dem_DTCOriginType</code>) und Zeiger auf den Statusbyte-Puffer (<code>uint8*</code>) auf; der Dem liefert das Ergebnis vom Typ <code>Dem_ReturnGetStatusOfDTCType</code> zurück.\n</li><li>Nach Abschluss der Statusabfrage übermittelt der <strong>Dcm</strong> dem <strong>Generic Scan Tool</strong> die entsprechende UDS-Antwort (<code>Positive or negative response()</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für die Interaktion zwischen Dcm und Dem bei UDS Service 0x19:</p>\n<ul class=\"fig-list\"><li>Der Dcm muss vor oder im Rahmen der Auswertung von Statusmasken-Anfragen die Verfügbarkeitsmaske via <code>Dem_DcmGetDTCStatusAvailabilityMask</code> validieren.\n</li><li>Zur Abfrage des konkreten UDS-Statusbytes eines DTCs über die BSW-internen Schnittstellen ist die Funktion <code>Dem_DcmGetStatusOfDTC</code> unter Angabe des Speicherorts (<code>Dem_DTCOriginType</code>) zu verwenden.\n</li><li>Entwickler müssen sicherstellen, dass Puffer für <code>Dem_UdsStatusByteType</code> bzw. <code>uint8*</code> gültig übergeben werden und die Rückgabewerte (<code>Std_ReturnType</code>, <code>Dem_ReturnGetStatusOfDTCType</code>) vor dem Zusammenbau der UDS-Response evaluiert werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-63d7d0df425047da", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm im Kontext der AUTOSAR Classic Platform (Diagnostic Stack). Dargestellt wird die Interaktion zur Abfrage des DTC-Status zwischen einem externen Diagnoseprüfgerät (Generic Scan Tool), dem Diagnostic Communication Manager (Dcm) und dem Diagnostic Event Manager (Dem).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten und Schnittstellen:</p>\n<ul class=\"fig-list\"><li><strong>Generic Scan Tool</strong>: Externer UDS-Tester / Diagnosetester.\n</li><li><strong>«module» Dcm</strong>: AUTOSAR-Basissoftwaremodul für Diagnosekommunikation.\n</li><li><strong>«module» Dem</strong>: AUTOSAR-Basissoftwaremodul für Fehlerspeicherverwaltung und DTC-Status.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li>UDS-Dienstaufruf: <code>Request: ReadDTCInformation(reportDTCByStatusMask)</code> (Service 0x19, Subfunktion 0x02) vom Tester an den Dcm.\n</li><li>C-API: <code>Dem_DcmGetDTCStatusAvailabilityMask(Std_ReturnType, Dem_UdsStatusByteType*)</code> zwischen Dcm und Dem.\n</li><li>C-API: <code>Dem_DcmGetStatusOfDTC(Dem_ReturnGetStatusOfDTCType, uint32, Dem_DTCOriginType, uint8*)</code> zwischen Dcm und Dem.\n</li><li>Diagnose-Antwort: <code>Positive or negative response()</code> vom Dcm an das Generic Scan Tool.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Das <strong>Generic Scan Tool</strong> sendet die Diagnoseanfrage <code>Request: ReadDTCInformation(reportDTCByStatusMask)</code> synchron/asynchron an das Modul <strong>Dcm</strong>.\n</li><li>Der <strong>Dcm</strong> ruft am <strong>Dem</strong> synchron die Funktion <code>Dem_DcmGetDTCStatusAvailabilityMask(...)</code> auf, um die unterstützte UDS-Statusmaske (<code>Dem_UdsStatusByteType*</code>) zu ermitteln, und erhält den Rückgabewert (<code>Std_ReturnType</code>).\n</li><li>Anschließend ruft der <strong>Dcm</strong> am <strong>Dem</strong> die Funktion <code>Dem_DcmGetStatusOfDTC(...)</code> mit den Parametern DTC-Wert (<code>uint32</code>), DTC-Herkunft/Speicherort (<code>Dem_DTCOriginType</code>) und Zeiger auf den Statusbyte-Puffer (<code>uint8*</code>) auf; der Dem liefert das Ergebnis vom Typ <code>Dem_ReturnGetStatusOfDTCType</code> zurück.\n</li><li>Nach Abschluss der Statusabfrage übermittelt der <strong>Dcm</strong> dem <strong>Generic Scan Tool</strong> die entsprechende UDS-Antwort (<code>Positive or negative response()</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für die Interaktion zwischen Dcm und Dem bei UDS Service 0x19:</p>\n<ul class=\"fig-list\"><li>Der Dcm muss vor oder im Rahmen der Auswertung von Statusmasken-Anfragen die Verfügbarkeitsmaske via <code>Dem_DcmGetDTCStatusAvailabilityMask</code> validieren.\n</li><li>Zur Abfrage des konkreten UDS-Statusbytes eines DTCs über die BSW-internen Schnittstellen ist die Funktion <code>Dem_DcmGetStatusOfDTC</code> unter Angabe des Speicherorts (<code>Dem_DTCOriginType</code>) zu verwenden.\n</li><li>Entwickler müssen sicherstellen, dass Puffer für <code>Dem_UdsStatusByteType</code> bzw. <code>uint8*</code> gültig übergeben werden und die Rückgabewerte (<code>Std_ReturnType</code>, <code>Dem_ReturnGetStatusOfDTCType</code>) vor dem Zusammenbau der UDS-Response evaluiert werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-dffd4a9f4f6752be", "to": "FIG-63d7d0df425047da", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
